int extractMissing(const juce::File& targetDir)
{
    if (!targetDir.exists()) targetDir.createDirectory();
    int written = 0;
    for (auto& p : getAll())
    {
        auto safe = juce::String(p.name).replaceCharacters(" /\\:*?\"<>|", "__________");
        auto file = targetDir.getChildFile(safe + ".didasynthpreset");
        if (! file.existsAsFile())
        {
            file.replaceWithText(juce::String::fromUTF8(p.json));
            ++written;
        }
    }
    return written;
}

